/// <summary>
///    AVA <c>initDataSources</c> method.
/// </summary>
public void initDataSources()
{
    Query                   locQuery;
    QueryBuildDataSource    locQbdsBase;
    QueryBuildDataSource    locQbdsContactPersonInfoCust;
    QueryBuildDataSource    locQbdsContactPersonDataCust;
    QueryBuildDataSource    locQbdsContactPersonInfoChain;
    QueryBuildDataSource    locQbdsContactPersonDataChain;

    locQuery                        = AVAPriceIncreaseCustomersTable_DS.query();
    locQbdsBase                     = AVAPriceIncreaseCustomersTable_DS.queryBuildDataSource();

    locQbdsContactPersonInfoCust    = locQuery.dataSourceTable(tableNum(ContactPerson), 1);
    locQbdsContactPersonInfoCust.clearLinks();
    locQbdsContactPersonInfoCust.addLink(   fieldNum(AVAPriceIncreaseCustomersTable, ContactPersonIdPriceInfoCust),
                                            fieldNum(ContactPerson, ContactPersonId)                                );
    locQbdsContactPersonInfoCust.relations(false);

    locQbdsContactPersonDataCust    = locQuery.dataSourceTable(tableNum(ContactPerson), 2);
    locQbdsContactPersonDataCust.clearLinks();
    locQbdsContactPersonDataCust.addLink(   fieldNum(AVAPriceIncreaseCustomersTable, ContactPersonIdPriceDataCust),
                                            fieldNum(ContactPerson, ContactPersonId)                                );
    locQbdsContactPersonDataCust.relations(false);

    locQbdsContactPersonInfoChain   = locQuery.dataSourceTable(tableNum(ContactPerson), 3);
    locQbdsContactPersonInfoChain.clearLinks();
    locQbdsContactPersonInfoChain.addLink(  fieldNum(AVAPriceIncreaseCustomersTable, ContactPersonIdPriceInfoChain),
                                            fieldNum(ContactPerson, ContactPersonId)                                );
    locQbdsContactPersonInfoChain.relations(false);

    locQbdsContactPersonDataChain   = locQuery.dataSourceTable(tableNum(ContactPerson), 4);
    locQbdsContactPersonDataChain.clearLinks();
    locQbdsContactPersonDataChain.addLink(  fieldNum(AVAPriceIncreaseCustomersTable, ContactPersonIdPriceDataChain),
                                            fieldNum(ContactPerson, ContactPersonId)                                );
    locQbdsContactPersonInfoChain.relations(false);
}

