/// <summary>
///    AVA <c>dialogGetPriceIncreasePercentage</c> method.
/// </summary>
/// <param name="_avaPriceIncreasePercentage">
///    <c>AVAPriceIncreasePercentage</c> as type
/// </param>
/// <returns>
///    <c>AVAPriceIncreasePercentage</c> as return value
/// </returns>
public AVAPriceIncreasePercentage dialogGetPriceIncreasePercentage(AVAPriceIncreasePercentage _avaPriceIncreasePercentage = 0.0)
{
    AVAPriceIncreasePercentage  retVal;

    Dialog                      dialog;
    DialogGroup                 dialogGroup;
    DialogField                 dialogAVAPriceIncreasePercentage;

    retVal = _avaPriceIncreasePercentage;

    dialog = new Dialog(strfmt("@SYS82282", "@NDX:NXAPriceIncreaseSetMarkedHelp"));

    dialogGroup                         = dialog.addGroup();
    dialogGroup.caption("@NDX:NXAPriceIncreaseSetMarked");
    dialogAVAPriceIncreasePercentage    = dialog.addFieldValue(extendedTypeStr(AVAPriceIncreasePercentage), retVal);

    dialog.run();

    if (dialog.closedOk())
    {
        //get values from the dialog fields
        retVal = dialogAVAPriceIncreasePercentage.value();
    }
    else
    {
        retVal = _avaPriceIncreasePercentage;
    }

    return retVal;
}

/// <summary>
///    AVA <c>dialogGetPriceIncreaseProductGroupAndPercentage</c> method.
/// </summary>
/// <param name="_kcs_GoodsId">
///    <c>KCS_GoodsId</c> as type
/// </param>
/// <param name="_avaPriceIncreasePercentage">
///    <c>AVAPriceIncreasePercentage</c> as type
/// </param>
/// <returns>
///    <c>AVAPriceIncreasePercentage</c> as return value
/// </returns>
public container dialogGetPriceIncreaseProductGroupAndPercentage(   KCS_GoodsId                _kcs_GoodsId,
                                                                    AVAPriceIncreasePercentage _avaPriceIncreasePercentage = 0.0)
{
    KCS_GoodsId                 retValGoodsId;
    AVAPriceIncreasePercentage  retValPercentage;

    Dialog                      dialog;
    DialogGroup                 dialogGroup;
    DialogField                 dialogKCS_GoodsId;
    DialogField                 dialogAVAPriceIncreasePercentage;

    retValGoodsId       = _kcs_GoodsId;
    retValPercentage    = _avaPriceIncreasePercentage;

    dialog = new Dialog(strfmt("@SYS82282", "@NDX:NXAPriceIncreaseGoodGroupLoadHelp"));

    dialogGroup                         = dialog.addGroup();
    dialogGroup.caption("@NDX:NXAPriceIncreaseGoodGroupLoad");
    dialogKCS_GoodsId                   = dialog.addFieldValue(extendedTypeStr(KCS_GoodsId),                retValGoodsId   );
    dialogAVAPriceIncreasePercentage    = dialog.addFieldValue(extendedTypeStr(AVAPriceIncreasePercentage), retValPercentage);

    dialog.run();

    if (dialog.closedOk())
    {
        //get values from the dialog fields
        retValGoodsId       = dialogKCS_GoodsId.value();
        retValPercentage    = dialogAVAPriceIncreasePercentage.value();
    }
    else
    {
        retValGoodsId       = _kcs_GoodsId;
        retValPercentage    = _avaPriceIncreasePercentage;
    }

    return [retValGoodsId, retValPercentage];
}

/// <summary>
///    AVA <c>active</c> method.
/// </summary>
/// <returns>
///    <c>int</c> as return value
/// </returns>
public int active()
{
    int                     retVal;

    FormDataSource          locFormDataSource;
    AVAPriceIncreaseTable   locTableBuffer;
    FormDateControl         locFormDateControl;
    Query                   locQuery;
    QueryBuildDataSource    locQbdsBase;

    retVal                  = super();

    locFormDataSource       = AVAPriceIncreaseTable_DS;
    locTableBuffer          = locFormDataSource.cursor();

    if(     locTableBuffer.Status == AVAPriceIncreaseStatus::JournalCreated 
        ||  locTableBuffer.Status == AVAPriceIncreaseStatus::JournalPosted 
        ||  locTableBuffer.Status == AVAPriceIncreaseStatus::PriceListsCreated  )
    {
        locFormDataSource.allowEdit(false);
    }
    else
    {
        locFormDataSource.allowEdit(true);
    }

    if(locFormDataSource.allowEdit())
    {
        locFormDateControl  = element.design().controlName(formControlStr(AVAPriceIncreaseTable, Grid_FromDate));

        if(locTableBuffer.Status == AVAPriceIncreaseStatus::New)
        {
            locFormDateControl.allowEdit(true);
        }
        else
        {
            locFormDateControl.allowEdit(false);
        }
    }

    /*
    locAVAPriceIncreasePriceDiscGroup.addFromAVAPriceIncreaseTable(locTableBuffer);
    locAVAPriceIncreasePriceDiscGroup.countPriceGroupMembersFromAVAPriceIncreaseTable(locTableBuffer);
    */

    locQuery                        = AVAPriceIncreaseCustomersTableGrpView_DS.query();
    locQbdsBase                     = AVAPriceIncreaseCustomersTableGrpView_DS.queryBuildDataSource();
    SysQuery::findOrCreateRange(locQbdsBase, fieldNum(AVAPriceIncreaseCustomersTableGrpView, PriceIncreaseSet)).value(queryValue(locTableBuffer.PriceIncreaseSet));

    return retVal;
}

