/// <summary>
///    AVA <c>clicked</c> method.
/// </summary>
public void clicked()
{
    AVAPriceIncreaseLine    locAVAPriceIncreaseLine;
    MultiSelectionHelper    helper;

    helper              = MultiSelectionHelper::construct();

    super();

    helper.parmDatasource(AVAPriceIncreaseLine_DS);
    locAVAPriceIncreaseLine = helper.getFirst();

    ttsbegin;
    while (locAVAPriceIncreaseLine.RecId != 0)
    {
        locAVAPriceIncreaseLine.selectForUpdate(true);
        locAVAPriceIncreaseLine.delete();

        locAVAPriceIncreaseLine = helper.getNext();
    }
    ttscommit;

    AVAPriceIncreaseLine_DS.research(true);
}

