/// <summary>
///    AVA <c>clicked</c> method.
/// </summary>
public void clicked()
{
    AVAPriceIncreaseTable                           locTableBuffer;
    AVAPriceIncreaseDetectPriceDiscGroupsContract   locAVAPriceIncreaseDetectPriceDiscGroupsContract;
    AVAPriceIncreaseDetectPriceDiscGroupsController locAVAPriceIncreaseDetectPriceDiscGroupsController;
    Args                                            locArgs;
    SysOperationStartResult                         locSysOperationStartResult;
    boolean                                         locDoResearch;

    locTableBuffer  = AVAPriceIncreaseTable_DS.cursor();

    super();

    locAVAPriceIncreaseDetectPriceDiscGroupsContract    = new AVAPriceIncreaseDetectPriceDiscGroupsContract();
    locArgs                                             = new Args();
    locArgs.caller(this);
    locArgs.record(locTableBuffer);

    locAVAPriceIncreaseDetectPriceDiscGroupsController  = AVAPriceIncreaseDetectPriceDiscGroupsController::newFromArgs(locArgs);
    locAVAPriceIncreaseDetectPriceDiscGroupsContract    = locAVAPriceIncreaseDetectPriceDiscGroupsController.getDataContractObject('_dataContract');
    locAVAPriceIncreaseDetectPriceDiscGroupsContract.parmArgs(locArgs);
    if(locTableBuffer.RecId)
    {
        locAVAPriceIncreaseDetectPriceDiscGroupsContract.parmAVAPriceIncreaseSet(locTableBuffer.PriceIncreaseSet);
    }
    locAVAPriceIncreaseDetectPriceDiscGroupsController.parmExecutionMode(SysOperationExecutionMode::Synchronous );

    locSysOperationStartResult                          = locAVAPriceIncreaseDetectPriceDiscGroupsController.startOperation();
    if(     locSysOperationStartResult == SysOperationStartResult::AddedToBatchQueue
        ||  locSysOperationStartResult == SysOperationStartResult::Started          )
    {
        locDoResearch   = true;
    }

    if(locDoResearch)
    {
        AVAPriceIncreasePriceDiscGroup_DS.research(true);
    }
}

/// <summary>
///    AVA <c>clicked</c> method.
/// </summary>
public void clicked()
{
    AVAPriceIncreasePriceDiscGroup  locTableBuffer;
    MultiSelectionHelper            helper;
    int                             locDeleted;
    int                             locNotPossible;

    helper      = MultiSelectionHelper::construct();

    super();

    helper.parmDatasource(AVAPriceIncreasePriceDiscGroup_DS);
    locTableBuffer   = helper.getFirst();

    ttsbegin;
    while (locTableBuffer.RecId != 0)
    {
        if(locTableBuffer.JournalNum == '')
        {
            locTableBuffer.selectForUpdate(true);
            locTableBuffer.delete();
            locDeleted++;
        }
        else
        {
            locNotPossible++;
        }

        locTableBuffer = helper.getNext();
    }
    ttscommit;

    AVAPriceIncreasePriceDiscGroup_DS.research(true);
}

/// <summary>
///    AVA <c>clicked</c> method.
/// </summary>
public void clicked()
{
    AVAPriceIncreasePriceDiscGroup  locTableBuffer;
    AVAPriceIncreaseTable           locAVAPriceIncreaseTable;
    MultiSelectionHelper            helper;
    boolean                         locDoResearch;
    boolean                         locResult;

    locAVAPriceIncreaseTable = AVAPriceIncreaseTable_DS.cursor();

    helper      = MultiSelectionHelper::construct();

    super();

    helper.parmDatasource(AVAPriceIncreasePriceDiscGroup_DS);
    locTableBuffer   = helper.getFirst();

    ttsbegin;
    while (locTableBuffer.RecId != 0)
    {
        if(locTableBuffer.JournalNum == '')
        {
            locResult = locTableBuffer.createPriceDiscAdmTableFromAVAPriceIncreaseTable(locAVAPriceIncreaseTable, locTableBuffer);
        }
        if(locResult)
        {
            locDoResearch = true;
        }

        locTableBuffer = helper.getNext();
    }
    ttscommit;

    if(locDoResearch)
    {
        AVAPriceIncreasePriceDiscGroup_DS.research(true);
    }
}

/// <summary>
///    AVA <c>clicked</c> method.
/// </summary>
public void clicked()
{
    AVAPriceIncreasePriceDiscGroup  locTableBuffer;
    AVAPriceIncreaseTable           locAVAPriceIncreaseTable;
    MultiSelectionHelper            helper;
    boolean                         locDoResearch;

    List                            locPriceGroupList;
    ListEnumerator                  locPriceGroupListEnumerator;
    int                             locPriceGroupListCount;

    AVAPriceIncreaseContract        locAVAPriceIncreaseContract;
    AVAPriceIncreaseController      locAVAPriceIncreaseController;
    SysOperationStartResult         locSysOperationStartResult;
    Args                            locArgs;

    locAVAPriceIncreaseTable = AVAPriceIncreaseTable_DS.cursor();

    helper      = MultiSelectionHelper::construct();

    super();

    locPriceGroupList = new List(Types::Int64);

    helper.parmDatasource(AVAPriceIncreasePriceDiscGroup_DS);
    locTableBuffer   = helper.getFirst();

    while (locTableBuffer.RecId != 0)
    {
        if(locTableBuffer.JournalNum == '')
        {
            locPriceGroupList.addEnd(locTableBuffer.RecId);
        }

        locTableBuffer = helper.getNext();
    }

    locPriceGroupListCount = locPriceGroupList.elements();
    if(locPriceGroupListCount)
    {
        locAVAPriceIncreaseContract     = new AVAPriceIncreaseContract();
        locArgs                         = new Args();
        locArgs.caller(this);
        locPriceGroupListEnumerator = locPriceGroupList.getEnumerator();
        locPriceGroupListEnumerator.reset();
        if(locPriceGroupListCount == 1)
        {
            locPriceGroupListEnumerator.moveNext();
            locTableBuffer  = AVAPriceIncreasePriceDiscGroup::findByRecId(locPriceGroupListEnumerator.current());
            locArgs.record(locTableBuffer);
        }
        else
        {
            locAVAPriceIncreaseContract.parmArgs(locArgs);
        }
        locDoResearch   = true;
        locAVAPriceIncreaseController   = AVAPriceIncreaseController::newFromArgs(locArgs);
        locAVAPriceIncreaseContract     = locAVAPriceIncreaseController.getDataContractObject('_dataContract');
        locAVAPriceIncreaseContract.parmArgs(locArgs);
        locAVAPriceIncreaseContract.parmRecIdList(locPriceGroupList);
        if(locTableBuffer.RecId)
        {
            locAVAPriceIncreaseContract.parmAVAPriceIncreaseSet(locTableBuffer.PriceIncreaseSet);
            locAVAPriceIncreaseContract.parmPriceGroupId(locTableBuffer.GroupId);
            locAVAPriceIncreaseContract.parmPriceDiscModule(locTableBuffer.Module);
            locAVAPriceIncreaseContract.parmPriceGroupType(locTableBuffer.Type);
        }
        locAVAPriceIncreaseController.parmExecutionMode(SysOperationExecutionMode::Synchronous );
        locSysOperationStartResult      = locAVAPriceIncreaseController.startOperation();
    }

    if(locDoResearch)
    {
        AVAPriceIncreasePriceDiscGroup_DS.research(true);
    }
}

/// <summary>
///    AVA <c>clicked</c> method.
/// </summary>
public void clicked()
{
    super();

    int64 notPostedJour = PriceDiscGroup.AVAcheckNotPostedJour();
    if (notPostedJour == 0)
    {
        AVAERPriceListController::constructForAzureBlob(PriceDiscGroup.GroupId);
    }
    else
    {
        Error(strFmt("@NDX:NXAPriceNotPostedJour",notPostedJour));
    }

}

