/// <summary>
///    AVA <c>clicked</c> method.
/// </summary>
public void clicked()
{
    AVAPriceIncreaseTable   locAVAPriceIncreaseTable;
    boolean                 locDoResearch;

    locAVAPriceIncreaseTable            = AVAPriceIncreaseTable_DS.cursor();
    if(locAVAPriceIncreaseTable.RecId)
    {
        AVAPriceIncreaseCustomersTable::deleteCustomerLines(locAVAPriceIncreaseTable.PriceIncreaseSet);
        locDoResearch = true;
    }
    if(locDoResearch)
    {
        AVAPriceIncreaseCustomersTable_DS.research(true);
        AVAPriceIncreaseCustomersTableGrpView_DS.research(true);
    }
}

/// <summary>
///    AVA <c>clicked</c> method.
/// </summary>
public void clicked()
{
    AVAPriceIncreaseCustomersTable  locTableBuffer;
    MultiSelectionHelper            helper;
    int                             locDeleted;
    int                             locNotPossible;

    helper      = MultiSelectionHelper::construct();

    super();

    helper.parmDatasource(AVAPriceIncreaseCustomersTable_DS);
    locTableBuffer   = helper.getFirst();

    ttsbegin;
    while (locTableBuffer.RecId != 0)
    {
        if(locTableBuffer.CustAccountNum != '')
        {
            locTableBuffer.selectForUpdate(true);
            locTableBuffer.delete();
            locDeleted++;
        }
        else
        {
            locNotPossible++;
        }

        locTableBuffer = helper.getNext();
    }
    ttscommit;

    AVAPriceIncreaseCustomersTable_DS.research(true);
    AVAPriceIncreaseCustomersTableGrpView_DS.research(true);
}
